rule.definition:
if(
  and(
    a!isNullOrEmpty(ri!tipoEventoFilter),
    a!isNullOrEmpty(ri!approbalUserFilter)
  ),
  null,
  #"SYSTEM_SYSRULES_queryRecordType_v4"(
    recordType: #"urn:appian:record-type:v1:2cdee35a-ab08-4dda-ab21-91870f840348",
    fields: #"SYSTEM_SYSRULES_aggregationFields"(
      groupings: {
        #"SYSTEM_SYSRULES_grouping"(
          field: #"urn:appian:record-field:v1:2cdee35a-ab08-4dda-ab21-91870f840348/5bea5efd-f7cf-48b1-bc8c-fc7a98628e14",
          alias: "APP_MAIL_POLLER_ID"
        )
      }
    ),
    filters: #"SYSTEM_SYSRULES_queryLogicalExpression"(
      operator: "AND",
      filters: {
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:2cdee35a-ab08-4dda-ab21-91870f840348/f54d21c3-52dc-4b3b-8134-98da2e9c25a3",
          operator: "in",
          value: a!defaultValue(ri!tipoEventoFilter, { 5, 6 })
        ),
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:2cdee35a-ab08-4dda-ab21-91870f840348/d905bb4a-e56a-417c-9504-66fbe5da37ca",
          operator: "=",
          value: ri!approbalUserFilter
        ),
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:2cdee35a-ab08-4dda-ab21-91870f840348/5bea5efd-f7cf-48b1-bc8c-fc7a98628e14",
          operator: "not null"
        )
      },
      ignoreFiltersWithEmptyValues: true
    ),
    pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1, batchSize: 5000),
    fetchTotalCount: true()
  ).data
)
